import type { User } from '../users/user.entity.js';
import type { ClientInfo, IssuedSession } from './sessions/sessions.types.js';

/** Who is performing an action. Every service method that touches user data takes one. */
export interface Actor {
  userId: string;
  via: 'web' | 'mcp';
}

export interface RequestAuth {
  actor: Actor;
  sessionId: string;
}

declare global {
  namespace Express {
    interface Request {
      /** Set by `SessionGuard` on authenticated routes. */
      auth?: RequestAuth;
    }
  }
}

export interface LoginContext extends ClientInfo {
  /** The session token the browser already holds, if any; it is revoked on login. */
  previousToken?: string;
}

export interface AuthResult {
  user: User;
  session: IssuedSession;
}
import { createParamDecorator, type ExecutionContext, SetMetadata } from '@nestjs/common';
import type { Request } from 'express';
import type { Actor } from './auth.types.js';

export const IS_PUBLIC_KEY = 'auth:isPublic';

/** Opts a route (or controller) out of authentication. Everything else requires a session. */
export const Public = () => SetMetadata(IS_PUBLIC_KEY, true);

/** The authenticated `Actor`. Only valid on routes that are not `@Public()`. */
export const CurrentActor = createParamDecorator((_data: unknown, ctx: ExecutionContext): Actor => {
  const actor = ctx.switchToHttp().getRequest<Request>().auth?.actor;
  if (!actor) throw new Error('@CurrentActor() used on a route that is not authenticated');
  return actor;
});
import {
  Body,
  Controller,
  Get,
  HttpCode,
  HttpStatus,
  Post,
  Req,
  Res,
  UseGuards,
} from '@nestjs/common';
import {
  type AuthResponse,
  type LoginRequest,
  loginRequestSchema,
  type SignupRequest,
  signupRequestSchema,
} from '@artifact-hub/shared';
import { SkipThrottle, ThrottlerGuard } from '@nestjs/throttler';
import type { Request, Response } from 'express';
import { LOGIN_EMAIL_THROTTLER } from '../common/rate-limit/rate-limit.module.js';
import { ZodValidationPipe } from '../common/validation/zod-validation.pipe.js';
import { toUserDto } from '../users/user.entity.js';
import { CurrentActor, Public } from './auth.decorators.js';
import { AuthService } from './auth.service.js';
import type { Actor, AuthResult, LoginContext } from './auth.types.js';
import { SessionCookieService } from './sessions/session-cookie.service.js';

@Controller('auth')
export class AuthController {
  constructor(
    private readonly auth: AuthService,
    private readonly cookie: SessionCookieService,
  ) {}

  @Public()
  @Post('signup')
  @UseGuards(ThrottlerGuard)
  @SkipThrottle({ [LOGIN_EMAIL_THROTTLER]: true })
  async signup(
    @Body(new ZodValidationPipe(signupRequestSchema)) body: SignupRequest,
    @Req() req: Request,
    @Res({ passthrough: true }) res: Response,
  ): Promise<AuthResponse> {
    return this.authResponse(res, await this.auth.signup(body, this.loginContext(req)));
  }

  @Public()
  @Post('login')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ThrottlerGuard)
  async login(
    @Body(new ZodValidationPipe(loginRequestSchema)) body: LoginRequest,
    @Req() req: Request,
    @Res({ passthrough: true }) res: Response,
  ): Promise<AuthResponse> {
    return this.authResponse(res, await this.auth.login(body, this.loginContext(req)));
  }

  /** Public so that logging out with an expired session still clears the cookie. */
  @Public()
  @Post('logout')
  @HttpCode(HttpStatus.NO_CONTENT)
  async logout(@Req() req: Request, @Res({ passthrough: true }) res: Response): Promise<void> {
    await this.auth.logout(this.cookie.read(req));
    this.cookie.clear(res);
  }

  @Get('me')
  async me(@CurrentActor() actor: Actor): Promise<AuthResponse> {
    return { user: toUserDto(await this.auth.me(actor)) };
  }

  private loginContext(req: Request): LoginContext {
    return {
      ip: req.ip ?? null,
      userAgent: req.get('user-agent') ?? null,
      previousToken: this.cookie.read(req),
    };
  }

  private authResponse(res: Response, { user, session }: AuthResult): AuthResponse {
    this.cookie.set(res, session.token, session.expiresAt);
    return { user: toUserDto(user) };
  }
}
