export const loginRequestSchema = z.object({
  email: emailSchema,
  password: z.string().min(1, 'Enter your password.').max(PASSWORD_MAX_LENGTH),
});

export type LoginRequest = z.infer<typeof loginRequestSchema>;

export const userSchema = z.object({
  id: z.uuid(),
  email: z.string(),
  displayName: z.string(),
  createdAt: z.iso.datetime(),
});

export type User = z.infer<typeof userSchema>;

/** Response of signup, login and `GET /api/auth/me`. */
export const authResponseSchema = z.object({ user: userSchema });

export type AuthResponse = z.infer<typeof authResponseSchema>;
# Local development stack with hot reload: `pnpm dev:docker`.
#   postgres  Postgres 16 on :5432 (also creates artifact_hub_test for the e2e suite)
#   api       builds packages/shared, applies migrations, then runs NestJS and the shared
#             package in watch mode on :3000
#   web       Vite dev server on :5173 (proxies /api and /mcp to the api service)
# `docker compose up -d postgres` starts only the database, for `pnpm dev` on the host.

x-dev: &dev
  build:
    context: .
    dockerfile: docker/Dockerfile.dev
  image: artifact-hub-dev
  volumes:
    - .:/app
    # Keep the image's dependencies visible over the source mount. `pnpm dev:docker` passes
    # --renew-anon-volumes so these are refreshed from the image after a lockfile change.
    - /app/node_modules
    - /app/apps/api/node_modules
    - /app/apps/web/node_modules
    - /app/packages/shared/node_modules

services:
  postgres:
    image: postgres:16-alpine
    environment:
      POSTGRES_USER: artifact_hub
      POSTGRES_PASSWORD: artifact_hub
      POSTGRES_DB: artifact_hub
    ports:
      - '5432:5432'
    volumes:
      - pgdata:/var/lib/postgresql/data
      - ./docker/postgres-init:/docker-entrypoint-initdb.d:ro
    healthcheck:
      test: ['CMD-SHELL', 'pg_isready -U artifact_hub -d artifact_hub']
      interval: 2s
      timeout: 3s
      retries: 30

  api:
    <<: *dev
    command: >
      sh -c "pnpm --filter @artifact-hub/shared build &&
             pnpm --filter @artifact-hub/api db:migrate &&
             pnpm --parallel --filter @artifact-hub/shared --filter @artifact-hub/api dev"
    environment:
      NODE_ENV: development
      PORT: 3000
      APP_BASE_URL: http://localhost:5173
      LOG_LEVEL: debug
      DATABASE_URL: postgres://artifact_hub:artifact_hub@postgres:5432/artifact_hub
    ports:
      - '3000:3000'
    depends_on:
      postgres:
        condition: service_healthy
    healthcheck:
      test: ['CMD-SHELL', 'wget -qO- http://localhost:3000/api/health || exit 1']
      interval: 5s
      timeout: 3s
      retries: 60
      start_period: 20s

  web:
    <<: *dev
    command: pnpm --filter @artifact-hub/web dev --host 0.0.0.0
    environment:
      VITE_API_PROXY_TARGET: http://api:3000
    ports:
      - '5173:5173'
    depends_on:
      # The api service builds packages/shared, which the web app imports.
      api:
        condition: service_healthy

volumes:
  pgdata:
# Production image: one container serving the API, the MCP endpoint and the built SPA.

FROM node:22-alpine AS base
ENV PNPM_HOME=/pnpm \
    PATH=/pnpm:$PATH \
    COREPACK_ENABLE_DOWNLOAD_PROMPT=0
RUN corepack enable
WORKDIR /app

FROM base AS build
COPY pnpm-lock.yaml pnpm-workspace.yaml package.json ./
COPY apps/api/package.json apps/api/
COPY apps/web/package.json apps/web/
COPY packages/shared/package.json packages/shared/
RUN --mount=type=cache,id=pnpm,target=/pnpm/store pnpm install --frozen-lockfile
COPY . .
RUN pnpm --filter @artifact-hub/shared build \
 && pnpm --filter @artifact-hub/web build \
 && pnpm --filter @artifact-hub/api build
# Standalone API directory with production dependencies only (workspace packages copied in).
RUN --mount=type=cache,id=pnpm,target=/pnpm/store \
    pnpm --filter @artifact-hub/api deploy --prod --legacy /out/api

FROM node:22-alpine AS runtime
ENV NODE_ENV=production \
    PORT=3000 \
    WEB_DIST_DIR=/app/web
WORKDIR /app
COPY --from=build --chown=node:node /out/api ./
COPY --from=build --chown=node:node /app/apps/web/dist ./web
USER node
EXPOSE 3000
# Apply pending migrations, then start the server.
CMD ["sh", "-c", "node dist/database/migrate.js && exec node dist/main.js"]
