import { DynamicModule, Global, Inject, Module } from '@nestjs/common';
import type { Env } from './config.types.js';

export const ENV = Symbol('ENV');

/** Injects the validated environment (`Env`). */
export const InjectEnv = () => Inject(ENV);

@Global()
@Module({})
export class ConfigModule {
  static forRoot(env: Env): DynamicModule {
    return {
      module: ConfigModule,
      providers: [{ provide: ENV, useValue: env }],
      exports: [ENV],
    };
  }
}
import type { z } from 'zod';
import type { envSchema } from './env.js';

/** The validated environment. */
export type Env = z.output<typeof envSchema>;
import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { ENV } from '../config/config.module.js';
import type { Env } from '../config/config.types.js';
import { buildDataSourceOptions } from './data-source.options.js';

@Module({
  imports: [
    TypeOrmModule.forRootAsync({
      inject: [ENV],
      useFactory: (env: Env) => ({
        ...buildDataSourceOptions(env.DATABASE_URL),
        autoLoadEntities: true,
        retryAttempts: 5,
        retryDelay: 2000,
      }),
    }),
  ],
})
export class DatabaseModule {}
import { Module } from '@nestjs/common';
import { HealthController } from './health.controller.js';

@Module({ controllers: [HealthController] })
export class HealthModule {}
import { ErrorCode } from '@artifact-hub/shared';
import type { PinoLogger } from 'nestjs-pino';
import type { DataSource } from 'typeorm';
import { AppError } from '../common/errors/app-error.js';
import { HealthController } from './health.controller.js';

const logger = { error: vi.fn() } as unknown as PinoLogger;

function controllerWith(query: () => Promise<unknown>) {
  return new HealthController({ query } as unknown as DataSource, logger);
}

describe('HealthController', () => {
  it('reports ok when the database answers', async () => {
    await expect(controllerWith(async () => [{ '?column?': 1 }]).check()).resolves.toEqual({
      status: 'ok',
      checks: { database: 'up' },
    });
  });

  it('throws SERVICE_UNAVAILABLE when the database query fails', async () => {
    const check = controllerWith(() => Promise.reject(new Error('ECONNREFUSED'))).check();
    await expect(check).rejects.toBeInstanceOf(AppError);
    await expect(check).rejects.toMatchObject({ code: ErrorCode.SERVICE_UNAVAILABLE });
  });
});
import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    globals: true,
    include: ['src/**/*.spec.ts'],
    passWithNoTests: true,
  },
});
import type { Session } from './session.entity.js';

export interface ClientInfo {
  ip: string | null;
  userAgent: string | null;
}

export interface IssuedSession {
  token: string;
  expiresAt: Date;
}

export interface ResolvedSession {
  /** Includes `user`. */
  session: Session;
  /** True when the expiry was extended, so the cookie must be re-sent with the new expiry. */
  extended: boolean;
}
import { InvalidEnvError, parseEnv } from './env.js';

const DATABASE_URL = 'postgres://user:pass@localhost:5432/db';

describe('parseEnv', () => {
  it('applies defaults for development', () => {
    expect(parseEnv({ DATABASE_URL })).toEqual({
      NODE_ENV: 'development',
      PORT: 3000,
      APP_BASE_URL: 'http://localhost:5173',
      LOG_LEVEL: 'info',
      DATABASE_URL,
