# Development image for docker-compose.yml: toolchain + workspace dependencies.
# The source is bind-mounted at runtime for hot reload; each service sets its own command.
FROM node:22-alpine
ENV PNPM_HOME=/pnpm \
    PATH=/pnpm:$PATH \
    COREPACK_ENABLE_DOWNLOAD_PROMPT=0
RUN corepack enable && mkdir -p /pnpm/store /app && chown -R node:node /pnpm /app
# Run as `node` (uid 1000) so files written to the mounted source (dist/) stay owned by the host user.
USER node
WORKDIR /app
RUN pnpm config set store-dir /pnpm/store --global

COPY --chown=node:node pnpm-lock.yaml pnpm-workspace.yaml package.json ./
COPY --chown=node:node apps/api/package.json apps/api/
COPY --chown=node:node apps/web/package.json apps/web/
COPY --chown=node:node packages/shared/package.json packages/shared/
RUN --mount=type=cache,id=pnpm-dev,target=/pnpm/store,uid=1000,gid=1000 \
    pnpm install --frozen-lockfile
import { Controller, Get, type INestApplication, Post } from '@nestjs/common';
import { apiErrorBodySchema, ErrorCode } from '@artifact-hub/shared';
import request from 'supertest';
import { z } from 'zod';
import { Public } from '../src/auth/auth.decorators.js';
import { AppError } from '../src/common/errors/app-error.js';
import { GENERIC_ERROR_MESSAGE } from '../src/common/errors/error-response.js';
import { createTestApp } from './create-test-app.js';

@Public()
@Controller('test-errors')
class ErrorsTestController {
  @Get('domain')
  domain() {
    throw new AppError(ErrorCode.CONFLICT, 'Already exists', { field: 'title' });
  }

  @Get('validation')
  validation() {
    z.object({ title: z.string().min(1) }).parse({ title: '' });
  }

  @Get('crash')
  crash() {
    throw new Error('secret internals');
  }

  @Post('echo')
  echo() {
    return { ok: true };
  }
}

describe('App (e2e)', () => {
  let app: INestApplication;

  beforeAll(async () => {
    app = await createTestApp({ controllers: [ErrorsTestController] });
  });

  afterAll(async () => {
    await app.close();
  });

  async function expectError(path: string, status: number, code: ErrorCode) {
    const res = await request(app.getHttpServer())
      .get(path)
      .set('X-Request-Id', 'req-1')
      .expect(status);
    const body = apiErrorBodySchema.parse(res.body);
    expect(body.error.code).toBe(code);
    expect(body.error.requestId).toBe('req-1');
    return body.error;
  }

  describe('GET /api/health', () => {
    it('returns ok with a generated request id', async () => {
      const res = await request(app.getHttpServer()).get('/api/health').expect(200);
      expect(res.body).toEqual({ status: 'ok', checks: { database: 'up' } });
      expect(res.headers['x-request-id']).toMatch(/^[0-9a-f-]{36}$/);
    });

    it('echoes a well-formed incoming request id', async () => {
      const res = await request(app.getHttpServer())
        .get('/api/health')
        .set('X-Request-Id', 'client-trace-42')
        .expect(200);
      expect(res.headers['x-request-id']).toBe('client-trace-42');
    });
  });

  describe('error responses', () => {
    it('returns NOT_FOUND for unknown routes', async () => {
      await expectError('/api/does-not-exist', 404, ErrorCode.NOT_FOUND);
    });

    it('returns domain errors with their code and details', async () => {
      const error = await expectError('/api/test-errors/domain', 409, ErrorCode.CONFLICT);
      expect(error).toMatchObject({ message: 'Already exists', details: { field: 'title' } });
    });

    it('returns VALIDATION_FAILED for zod errors', async () => {
      const error = await expectError(
        '/api/test-errors/validation',
        400,
        ErrorCode.VALIDATION_FAILED,
      );
      expect(error.details).toEqual([{ path: 'title', message: expect.any(String) }]);
    });

    it('hides unexpected errors behind a generic message', async () => {
      const error = await expectError('/api/test-errors/crash', 500, ErrorCode.INTERNAL_ERROR);
      expect(error.message).toBe(GENERIC_ERROR_MESSAGE);
      expect(JSON.stringify(error)).not.toContain('secret internals');
    });

    it('returns BAD_REQUEST for malformed JSON bodies', async () => {
      const res = await request(app.getHttpServer())
        .post('/api/test-errors/echo')
        .set('Content-Type', 'application/json')
        .send('{"broken":')
        .expect(400);
      expect(apiErrorBodySchema.parse(res.body).error.code).toBe(ErrorCode.BAD_REQUEST);
    });
  });
});
import { HttpStatus } from '@nestjs/common';
import { ErrorCode } from '@artifact-hub/shared';

export const ERROR_HTTP_STATUS: Record<ErrorCode, HttpStatus> = {
  BAD_REQUEST: HttpStatus.BAD_REQUEST,
  VALIDATION_FAILED: HttpStatus.BAD_REQUEST,
  UNAUTHENTICATED: HttpStatus.UNAUTHORIZED,
  FORBIDDEN: HttpStatus.FORBIDDEN,
  NOT_FOUND: HttpStatus.NOT_FOUND,
  CONFLICT: HttpStatus.CONFLICT,
  PAYLOAD_TOO_LARGE: HttpStatus.PAYLOAD_TOO_LARGE,
  ARTIFACT_TOO_LARGE: HttpStatus.PAYLOAD_TOO_LARGE,
  UNSUPPORTED_TYPE: HttpStatus.UNSUPPORTED_MEDIA_TYPE,
  UPLOAD_SESSION_EXPIRED: HttpStatus.GONE,
  UPLOAD_SESSION_USED: HttpStatus.CONFLICT,
  SHARE_RECIPIENT_UNKNOWN: HttpStatus.UNPROCESSABLE_ENTITY,
  RATE_LIMITED: HttpStatus.TOO_MANY_REQUESTS,
  AI_UNAVAILABLE: HttpStatus.SERVICE_UNAVAILABLE,
  SERVICE_UNAVAILABLE: HttpStatus.SERVICE_UNAVAILABLE,
  INTERNAL_ERROR: HttpStatus.INTERNAL_SERVER_ERROR,
};

/**
 * A domain error with a stable code. Services throw these; the HTTP filter and the
 * MCP adapter translate them for their transport.
 */
export class AppError extends Error {
  constructor(
    readonly code: ErrorCode,
    message: string,
    readonly details?: unknown,
  ) {
    super(message);
    this.name = 'AppError';
  }

  get status(): HttpStatus {
    return ERROR_HTTP_STATUS[this.code];
  }
}
import { QueryFailedError } from 'typeorm';

const UNIQUE_VIOLATION = '23505';

/** True when a query failed on a unique constraint, optionally a specific one. */
export function isUniqueViolation(error: unknown, constraint?: string): boolean {
  if (!(error instanceof QueryFailedError)) return false;
  const driverError = error.driverError as { code?: string; constraint?: string };
  return (
    driverError.code === UNIQUE_VIOLATION &&
    (constraint === undefined || driverError.constraint === constraint)
  );
}
