class ByteMeter {
  private total = 0;

  constructor(private readonly maxBytes: number) {}

  add(chunk: Buffer | string): Buffer {
    const buffer = typeof chunk === 'string' ? Buffer.from(chunk) : chunk;
    this.total += buffer.length;
