import type { Readable } from 'node:stream';
import type { ContentHint } from '../uploads/content/content.types.js';
import type { Artifact } from './artifact.entity.js';

/** Content for a new version, from a multipart upload, an upload session or MCP inline text. */
export interface NewContent extends ContentHint {
  stream: Readable;
}

export interface ArtifactPage {
  items: Artifact[];
  nextCursor: string | null;
}

/** Position in a list ordered by `(updatedAt DESC, id DESC)`. */
export interface ListCursor {
  updatedAt: Date;
  id: string;
}

import { ErrorCode } from '@artifact-hub/shared';
import { z } from 'zod';
import { AppError } from '../common/errors/app-error.js';
import type { ListCursor } from './artifacts.types.js';

const cursorSchema = z.object({ u: z.iso.datetime(), i: z.guid() });

/** An opaque cursor: base64url JSON of the last item's sort key. */
export function encodeListCursor({ updatedAt, id }: ListCursor): string {
  return Buffer.from(JSON.stringify({ u: updatedAt.toISOString(), i: id })).toString('base64url');
}

export function decodeListCursor(cursor: string): ListCursor {
  try {
    const { u, i } = cursorSchema.parse(JSON.parse(Buffer.from(cursor, 'base64url').toString()));
    return { updatedAt: new Date(u), id: i };
  } catch {
    throw new AppError(ErrorCode.BAD_REQUEST, 'The page cursor is invalid. Start from the first page.');
  }
}

import { ErrorCode } from '@artifact-hub/shared';
import { decodeListCursor, encodeListCursor } from './list-cursor.js';

describe('list cursor', () => {
  it('round-trips the sort key', () => {
    const position = {
      updatedAt: new Date('2026-10-03T12:34:56.789Z'),
      id: '5b0c3e5e-8d0a-4c56-9a3b-2f1d7c9e4a10',
    };
    const cursor = encodeListCursor(position);
    expect(cursor).toMatch(/^[A-Za-z0-9_-]+$/);
    expect(decodeListCursor(cursor)).toEqual(position);
  });

  it.each([
    'not-base64-json',
    Buffer.from('{"u":"yesterday","i":"5b0c3e5e-8d0a-4c56-9a3b-2f1d7c9e4a10"}').toString(
      'base64url',
    ),
    Buffer.from('{"u":"2026-10-03T12:34:56.789Z","i":"1; DROP TABLE"}').toString('base64url'),
  ])('rejects the malformed cursor %j with BAD_REQUEST', (cursor) => {
    expect(() => decodeListCursor(cursor)).toThrow(
      expect.objectContaining({ code: ErrorCode.BAD_REQUEST }),
    );
  });
});

