/** The artifact with its owner and current version. `NOT_FOUND` if missing or not visible. */
async get(actor: Actor, id: string): Promise<Artifact> {
  const artifact = idSchema.safeParse(id).success
    ? await this.artifacts.findOne({
        where: { id },
        relations: { owner: true, currentVersion: true },
      })
    : null;
  if (!artifact) throw new AppError(ErrorCode.NOT_FOUND, ARTIFACT_NOT_FOUND_MESSAGE);
  this.access.assertCan(actor, 'view', artifact);
  return artifact;
}

/** The actor's own published artifacts, most recently updated first. */
async listMine(actor: Actor, query: ArtifactListQuery): Promise<ArtifactPage> {
  const qb = this.artifacts
    .createQueryBuilder('artifact')
    .innerJoinAndSelect('artifact.owner', 'owner')
    .leftJoinAndSelect('artifact.currentVersion', 'currentVersion')
    .where('artifact.ownerId = :userId', { userId: actor.userId })
    .andWhere('artifact.deletedAt IS NULL')
    .andWhere("artifact.status = 'published'")
    .orderBy('artifact.updatedAt', 'DESC')
    .addOrderBy('artifact.id', 'DESC')
    // Joins are to-one, so LIMIT is safe (no row multiplication).
    .limit(query.limit + 1);

  if (query.cursor) {
    const after = decodeListCursor(query.cursor);
    qb.andWhere('(artifact.updatedAt, artifact.id) < (:updatedAt, :id)', after);
  }

  const rows = await qb.getMany();
  const items = rows.slice(0, query.limit);
  const last = items.at(-1);
  return {
    items,
    nextCursor: rows.length > query.limit && last ? encodeListCursor(last) : null,
  };

