  describe('GET /api/artifacts (mine)', () => {
    let carol: TestUser;
    const titles = ['First', 'Second', 'Third'];

    beforeAll(async () => {
      carol = await users.create('Carol');
      for (const title of titles) {
        await publish(carol, fixtures.markdown, 'a.md', { title }).expect(201);
      }
    });

    it('pages through my artifacts, newest first', async () => {
      const first = artifactListResponseSchema.parse(
        (await list(carol, { limit: 2 }).expect(200)).body,
      );
      expect(first.items.map((item) => item.title)).toEqual(['Third', 'Second']);
      expect(first.nextCursor).toEqual(expect.any(String));

      const second = artifactListResponseSchema.parse(
        (await list(carol, { limit: 2, cursor: first.nextCursor ?? '' }).expect(200)).body,
      );
      expect(second.items.map((item) => item.title)).toEqual(['First']);
      expect(second.nextCursor).toBeNull();
    });

    it("never includes other users' artifacts", async () => {
      const page = artifactListResponseSchema.parse((await list(bob).expect(200)).body);
      expect(page.items).toEqual([]);
    });

    it("returns nothing when filtering by another user's id", async () => {
      const service = app.get(ArtifactsService);
      const asCarol = await service.list({ userId: carol.id, via: 'web' }, { limit: 10 });
      expect(asCarol.items).toHaveLength(titles.length);

      const asBob = await service.list(
        { userId: bob.id, via: 'web' },
        { ownerId: carol.id, limit: 10 },
      );
      expect(asBob.items).toEqual([]);
    });

    it('rejects an invalid cursor or limit', async () => {
      expect(errorOf(await list(carol, { cursor: 'garbage' }).expect(400)).code).toBe(
        ErrorCode.BAD_REQUEST,
      );
      expect(errorOf(await list(carol, { limit: 500 }).expect(400)).code).toBe(
        ErrorCode.VALIDATION_FAILED,
      );
    });
  });
});

