import {
  authResponseSchema,
  type LoginRequest,
  type SignupRequest,
  type User,
} from '@artifact-hub/shared';
import { isApiError } from '@/lib/api/api-error.ts';
import { apiRequest } from '@/lib/api/client.ts';

/** Cache key of the signed-in user: a `User`, or `null` when signed out. */
export const currentUserQueryKey = ['auth', 'me'] as const;

export async function fetchCurrentUser(): Promise<User | null> {
  try {
    return (await apiRequest('/auth/me', { schema: authResponseSchema })).user;
  } catch (error) {
    if (isApiError(error, 'UNAUTHENTICATED')) return null;
    throw error;
  }
}

export async function login(body: LoginRequest): Promise<User> {
  return (await apiRequest('/auth/login', { method: 'POST', body, schema: authResponseSchema }))
    .user;
}

export async function signup(body: SignupRequest): Promise<User> {
  return (await apiRequest('/auth/signup', { method: 'POST', body, schema: authResponseSchema }))
    .user;
}

export function logout(): Promise<void> {
  return apiRequest('/auth/logout', { method: 'POST' });
}
import type { User } from '@artifact-hub/shared';
import { hashKey, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { currentUserQueryKey, fetchCurrentUser, login, logout, signup } from './auth-api.ts';

export function useCurrentUser() {
  return useQuery({
    queryKey: currentUserQueryKey,
    queryFn: fetchCurrentUser,
    // Changes only through login/signup/logout (which update the cache) or a 401.
    staleTime: Infinity,
  });
}

function useSetCurrentUser() {
  const queryClient = useQueryClient();
  return (user: User) => queryClient.setQueryData(currentUserQueryKey, user);
}

export function useLogin() {
  const setCurrentUser = useSetCurrentUser();
  return useMutation({ mutationFn: login, onSuccess: setCurrentUser });
}

export function useSignup() {
  const setCurrentUser = useSetCurrentUser();
  return useMutation({ mutationFn: signup, onSuccess: setCurrentUser });
}

export function useLogout() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: logout,
    onSuccess: () => {
      // Mark the session as signed out (the route guards react to it), then drop everything
      // else cached for this user. `clear()` would also detach the guards from the user query.
      queryClient.setQueryData(currentUserQueryKey, null);
      const currentUserHash = hashKey(currentUserQueryKey);
      queryClient.removeQueries({ predicate: (query) => query.queryHash !== currentUserHash });
    },
  });
}
import { QueryClientProvider } from '@tanstack/react-query';
import { render } from '@testing-library/react';
import { createMemoryRouter, RouterProvider } from 'react-router';
import { createQueryClient } from '@/lib/query-client.ts';
import { routes } from '@/routes/routes.tsx';

/** Renders the real routes at `path`, with a fresh query cache. */
export function renderApp(path: string) {
  const router = createMemoryRouter(routes, { initialEntries: [path] });
  const queryClient = createQueryClient();
  const utils = render(
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>,
  );
  const location = () => `${router.state.location.pathname}${router.state.location.search}`;
  return { ...utils, router, queryClient, location };
}
import { ErrorCode, type User } from '@artifact-hub/shared';
import { vi } from 'vitest';

interface Account {
  user: User;
  password: string;
}

function json(status: number, body?: unknown): Response {
  if (body === undefined) return new Response(null, { status });
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

function error(status: number, code: ErrorCode, message: string): Response {
  return json(status, { error: { code, message, requestId: 'test-req' } });
}

/**
 * Stubs `fetch` with an in-memory version of the auth endpoints, so component tests run the
 * real API client, hooks and routes.
 */
export function installFakeAuthApi() {
  const accounts = new Map<string, Account>();
  let signedIn: User | null = null;

  const fetchMock = vi.fn(async (input: string, init: RequestInit = {}) => {
    const body = init.body ? JSON.parse(String(init.body)) : undefined;
    const route = `${init.method ?? 'GET'} ${input}`;

    switch (route) {
      case 'GET /api/auth/me':
        return signedIn
          ? json(200, { user: signedIn })
          : error(401, ErrorCode.UNAUTHENTICATED, 'Please log in.');
      case 'POST /api/auth/login': {
        const account = accounts.get(body.email);
        if (!account || account.password !== body.password) {
          return error(401, ErrorCode.UNAUTHENTICATED, 'Invalid email or password.');
        }
        signedIn = account.user;
        return json(200, { user: signedIn });
      }
      case 'POST /api/auth/signup': {
        if (accounts.has(body.email)) {
          return error(409, ErrorCode.CONFLICT, 'An account with this email already exists.');
        }
        const user: User = {
          id: crypto.randomUUID(),
          email: body.email,
          displayName: body.displayName,
          createdAt: new Date().toISOString(),
        };
        accounts.set(body.email, { user, password: body.password });
        signedIn = user;
        return json(201, { user });
      }
      case 'POST /api/auth/logout':
        signedIn = null;
        return json(204);
      default:
        return error(404, ErrorCode.NOT_FOUND, `No fake for ${route}`);
    }
  });
  vi.stubGlobal('fetch', fetchMock);

  return {
    fetchMock,
    addAccount(email: string, password: string, displayName = 'Ada Lovelace') {
      const user: User = {
        id: crypto.randomUUID(),
        email,
        displayName,
        createdAt: new Date().toISOString(),
      };
      accounts.set(email, { user, password });
      return user;
    },
    signIn(user: User) {
      signedIn = user;
    },
    /** Simulates the session expiring on the server. */
    expireSession() {
      signedIn = null;
    },
    calls(route: string) {
      return fetchMock.mock.calls.filter(
        ([url, init]) => `${init?.method ?? 'GET'} ${url}` === route,
      ).length;
    },
  };
}
