      });
    });

    it('serves binary types without a charset', async () => {
      const res = await content(ada, pngId).buffer(true).expect(200);
      expect(res.headers['content-type']).toBe('image/png');
      expect(Buffer.from(res.body as Buffer).equals(fixtures.png)).toBe(true);
    });

