      <div className="h-[60vh]">
        <ViewerLoading />
      </div>
    );
  }
  return <ArtifactDetails artifact={artifact} />;
}

function ArtifactDetails({ artifact }: { artifact: Artifact }) {
  const viewerRef = useRef<HTMLDivElement>(null);
  const version = artifact.currentVersion;

  return (
