import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { chromium } from 'playwright-core';

const BASE = 'http://localhost:5173';
const PDF = '/home/work/projects/artifact_hub/docs/requirements.pdf';
const OUT = process.cwd();
const email = `pdf-smoke-${Date.now()}@smoke.e2e.test`;
const pdfBytes = readFileSync(PDF);
const sha = (b) => createHash('sha256').update(b).digest('hex');

const browser = await chromium.launch({ executablePath: '/snap/bin/chromium', headless: true });
const context = await browser.newContext({ viewport: { width: 1400, height: 1000 } });
const page = await context.newPage();
const problems = [];
page.on('console', (m) => m.type() === 'error' && problems.push(`console: ${m.text()}`));
page.on('pageerror', (e) => problems.push(`pageerror: ${e.message}`));
page.on('requestfailed', (r) => problems.push(`requestfailed: ${r.url()} ${r.failure()?.errorText}`));
const step = (s) => console.log(`✓ ${s}`);

try {
  // Sign up
  await page.goto(`${BASE}/signup`);
  await page.getByLabel('Name').fill('PDF Smoke');
  await page.getByLabel('Email').fill(email);
  await page.getByLabel('Password').fill('correct horse battery');
  await page.getByRole('button', { name: 'Create account' }).click();
  await page.getByRole('heading', { name: 'My artifacts' }).waitFor();
  step('signed up, gallery shown');

  // Publish the PDF through the dialog
  await page.getByRole('banner').getByRole('button', { name: 'Publish' }).click();
  const dialog = page.getByRole('dialog', { name: 'Publish an artifact' });
  await dialog.waitFor();
  await dialog.locator('input[type=file]').setInputFiles(PDF);
  const title = await dialog.getByLabel('Title').inputValue();
  step(`file chosen, title prefilled: "${title}"`);
  await dialog.getByLabel('Tags').fill('requirements, PDF');
  const publishResponse = page.waitForResponse((r) => r.url().endsWith('/api/artifacts') && r.request().method() === 'POST');
  await dialog.getByRole('button', { name: 'Publish' }).click();
  const created = await (await publishResponse).json();
  const artifact = created.artifact;
  step(`POST /api/artifacts → ${(await publishResponse).status()}, mimeType=${artifact.currentVersion.mimeType}, size=${artifact.currentVersion.sizeBytes} (file ${pdfBytes.length}), sha256 matches=${artifact.currentVersion.sha256 === sha(pdfBytes)}`);
  await page.waitForURL(`**/artifacts/${artifact.id}`);
  step(`navigated to /artifacts/${artifact.id}`);

  // pdf.js renders pages into canvases
  const firstPage = page.locator('canvas[aria-label^="Page 1 of"]');
  await firstPage.waitFor({ timeout: 20000 });
  const pageCount = await page.locator('canvas[aria-label^="Page "]').count();
  const label = await firstPage.getAttribute('aria-label');
  // Wait until page 1 has actually been painted, then count non-white pixels.
  await page.waitForFunction(() => {
    const c = document.querySelector('canvas[aria-label^="Page 1 of"]');
    const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
    let ink = 0;
    for (let i = 0; i < d.length; i += 4 * 50) if (d[i] < 200) ink++;
    return ink > 100;
  }, null, { timeout: 20000 });
  step(`pdf.js rendered ${pageCount} canvas page(s) ("${label}") with visible content`);
  await page.screenshot({ path: `${OUT}/pdf-artifact-page.png` });

  // GET again: a fresh load of the page and the API
  await page.reload();
  await firstPage.waitFor({ timeout: 20000 });
  step('reload: PDF renders again');
  const api = context.request;
  const meta = await api.get(`${BASE}/api/artifacts/${artifact.id}`);
  step(`GET /api/artifacts/:id → ${meta.status()}, title="${(await meta.json()).artifact.title}"`);
  const content = await api.get(`${BASE}/api/artifacts/${artifact.id}/versions/1/content`);
  const body = await content.body();
  const h = content.headers();
  step(`GET content → ${content.status()}, ${h['content-type']}, ${body.length} bytes, identical=${sha(body) === sha(pdfBytes)}, csp sandbox=${h['content-security-policy']?.startsWith('sandbox')}`);
  const revalidate = await api.get(`${BASE}/api/artifacts/${artifact.id}/versions/1/content`, { headers: { 'If-None-Match': h.etag } });
  step(`GET content with If-None-Match → ${revalidate.status()}`);
  const download = await api.get(`${BASE}/api/artifacts/${artifact.id}/versions/1/content?download=1`);
  step(`GET content?download=1 → ${download.status()}, ${download.headers()['content-disposition']}`);

  // Gallery shows the new card
  await page.getByRole('link', { name: 'Artifact Hub' }).click();
  await page.getByRole('heading', { name: title, level: 2 }).waitFor();
  step('gallery lists the new artifact');
  await page.screenshot({ path: `${OUT}/gallery.png` });

  writeFileSync(`${OUT}/run.json`, JSON.stringify({ email, artifactId: artifact.id }));
} catch (error) {
  console.log(`✗ FAILED: ${error.message.split('\n')[0]}`);
  await page.screenshot({ path: `${OUT}/failure.png` }).catch(() => {});
  writeFileSync(`${OUT}/run.json`, JSON.stringify({ email }));
} finally {
  console.log(problems.length ? `Browser problems:\n  ${problems.join('\n  ')}` : 'No console errors or failed requests.');
  await browser.close();
}
EOF
