  const download = await api.get(`${BASE}/api/artifacts/${artifact.id}/versions/1/content?download=1`);
  step(`GET content?download=1 → ${download.status()}, ${download.headers()['content-disposition']}`);

  // Gallery shows the new card
  await page.getByRole('link', { name: 'Artifact Hub' }).click();
  await page.getByRole('heading', { name: title, level: 2 }).waitFor();
  step('gallery lists the new artifact');
  await page.screenshot({ path: `${OUT}/gallery.png` });

  writeFileSync(`${OUT}/run.json`, JSON.stringify({ email, artifactId: artifact.id }));
} catch (error) {
  console.log(`✗ FAILED: ${error.message.split('\n')[0]}`);
  await page.screenshot({ path: `${OUT}/failure.png` }).catch(() => {});
  writeFileSync(`${OUT}/run.json`, JSON.stringify({ email }));
} finally {
  console.log(problems.length ? `Browser problems:\n  ${problems.join('\n  ')}` : 'No console errors or failed requests.');
  await browser.close();
}
EOF
timeout 150 node pdf-flow.mjs 2>&1 | tail -25
